import { z } from 'zod';
import type { TelemetryService } from './TelemetryService';
import { findHub, requestHub } from '../library/HubClient';
import { getConfigManager } from './ConfigManager';
import { currentLibraryRoot } from './ProjectLibrary';
import {
  GuidanceDocumentSchema,
  guidancePayloadByteLength,
  GuidanceError,
  GuidanceSelectionSchema,
} from '../types/guidance';
import type { ChangeRequest } from '../types/change-request-types';

const GUIDANCE_TIMEOUT_MS = 5_000;
const resolutionSchema = z.object({
  accountId: z.string().min(1),
  guidance: z.array(GuidanceDocumentSchema),
});

export const assertGenerationGuidance = (request: ChangeRequest): void => {
  if (!request.guidanceAccountId) return;
  const config = getConfigManager();
  if (
    !config.isAuthenticated() ||
    config.getUserId() !== request.guidanceAccountId
  )
    throw new GuidanceError(
      'guidance_account_changed',
      'The saved context account changed; retry this generation.',
    );
};

const resolveGenerationGuidance = async (
  request: ChangeRequest,
): Promise<ChangeRequest> => {
  assertGenerationGuidance(request);
  const selection = GuidanceSelectionSchema.parse(
    request.guidanceSelection ?? {},
  );
  if (selection.mode === 'off') return { ...request, guidance: [] };
  const config = getConfigManager();
  const accountId = config.getUserId();
  if (!config.isAuthenticated() || !accountId)
    throw new GuidanceError(
      'guidance_auth_required',
      'Sign in to load saved context, or start this generation with --guidance off.',
    );
  const hub = await findHub(currentLibraryRoot());
  if (!hub)
    throw new Error(
      'Cannot load saved context. Run rivet open and retry, or use --guidance off for this generation.',
    );
  const resolution = resolutionSchema.parse(
    await requestHub({
      hub,
      endpoint: '/guidance/resolutions',
      body: { accountId, ...selection },
      timeoutMs: GUIDANCE_TIMEOUT_MS,
    }),
  );
  if (resolution.accountId !== accountId)
    throw new GuidanceError(
      'guidance_account_changed',
      'The saved context account changed; retry this generation.',
    );
  const prepared = {
    ...request,
    guidance: resolution.guidance,
    guidanceAccountId: accountId,
  };
  assertGenerationGuidance(prepared);
  return prepared;
};

export const prepareGenerationGuidance = async (
  request: ChangeRequest,
  telemetry?: Pick<TelemetryService, 'trackGuidanceOperation'>,
): Promise<ChangeRequest> => {
  const startedAt = Date.now();
  try {
    const prepared = await resolveGenerationGuidance(request);
    telemetry?.trackGuidanceOperation({
      operation: 'delivery',
      outcome: 'completed',
      durationMs: Date.now() - startedAt,
      documentCount: prepared.guidance?.length ?? 0,
      byteCount: guidancePayloadByteLength(prepared.guidance ?? []),
      mode: request.guidanceSelection?.mode ?? 'auto',
    });
    return prepared;
  } catch (error) {
    telemetry?.trackGuidanceOperation({
      operation: 'delivery',
      outcome: 'failed',
      durationMs: Date.now() - startedAt,
      errorCode:
        error instanceof GuidanceError ? error.code : 'guidance_unavailable',
    });
    throw error;
  }
};
